-- 2 champion fight(s) (LaunchBOS)
-- arena 0: setup Champion_0_Setup, warm-up Champion_0_WarmUp, combat Champion_0_Combat, won Champion_0_OnTimeOut, lost Champion_0_OnTimeOut, time-out Champion_0_OnTimeOut
if Champion_0_Setup ~= nil then Coop_Orig.Champion_0_Setup = Champion_0_Setup
	function Champion_0_Setup(a1, a2, a3) Coop_BOS_Setup(0) Coop_AllowMove = true Coop_Orig.Champion_0_Setup(a1, a2, a3) Coop_BOS_BringPlayers() Coop_AllowMove = false end end
if Champion_0_Combat ~= nil then Coop_Orig.Champion_0_Combat = Champion_0_Combat
	function Champion_0_Combat(a1, a2, a3) if Coop_BOS_Combat(0) then return Coop_Orig.Champion_0_Combat(a1, a2, a3) end end end
if Champion_0_OnTimeOut ~= nil then Coop_Orig.Champion_0_OnTimeOut = Champion_0_OnTimeOut
