-- the engine never ends a fight when the champion dies in MP: Coop_Tick (host, 1/s) does
function Coop_LevelTick()
	if Champion_0_OnTimeOut ~= nil and Coop_BOS_ChampionDead(0) then PrintDebug("[coop] champion of arena 0 is dead - Champion_0_OnTimeOut") Champion_0_OnTimeOut() end
	if Champion_1_OnTimeOut ~= nil and Coop_BOS_ChampionDead(1) then PrintDebug("[coop] champion of arena 1 is dead - Champion_1_OnTimeOut") Champion_1_OnTimeOut() end
end
